AssistantMessageToolRequest(name='create', tool_call_id='tooluse_efVjXCY8O9f5GfMqJd4FVd', arguments={'file_text': "/* ── Reset & Base ─────────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg-0:       #0a0a0b;
  --bg-1:       #111113;
  --bg-2:       #1a1a1e;
  --bg-3:       #222228;
  --border:     #2a2a32;
  --accent:     #e8c46a;
  --accent-dim: #c9a84c;
  --accent-glow:rgba(232,196,106,.18);
  --red:        #e85d5d;
  --text-0:     #f0f0f2;
  --text-1:     #b0b0b8;
  --text-2:     #6a6a78;
  --radius-sm:  6px;
  --radius-md:  12px;
  --radius-lg:  20px;
  --shadow:     0 4px 24px rgba(0,0,0,.55);
  --transition: .22s cubic-bezier(.4,0,.2,1);
  --font:       'Inter', system-ui, -apple-system, sans-serif;
}

html { scroll-behavior: smooth; }

body {
  background: var(--bg-0);
  color: var(--text-0);
  font-family: var(--font);
  font-size: 15px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; text-decoration: none; }
img { display: block; max-width: 100%; }
button { cursor: pointer; border: none; background: none; font-family: inherit; }
ul { list-style: none; }

/* ── Utilities ────────────────────────────────────────── */
.container {
  max-width: 1240px;
  margin: 0 auto;
  padding: 0 24px;
}

.badge {
  display: inline-block;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .06em;
  text-transform: uppercase;
  padding: 3px 9px;
  border-radius: 4px;
}
.badge--accent { background: var(--accent); color: #111; }
.badge--red    { background: var(--red);    color: #fff; }
.badge--ghost  { border: 1px solid var(--border); color: var(--text-1); }

.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: 32px;
  gap: 16px;
}
.section-header h2 {
  font-size: clamp(20px, 2.5vw, 26px);
  font-weight: 700;
  letter-spacing: -.02em;
}
.section-header h2 span { color: var(--accent); }
.view-all {
  font-size: 13px;
  font-weight: 600;
  color: var(--accent);
  white-space: nowrap;
  display: flex;
  align-items: center;
  gap: 4px;
  transition: gap var(--transition);
}
.view-all:hover { gap: 8px; }
.view-all svg { width: 14px; height: 14px; }

/* ── NAV ──────────────────────────────────────────────── */
.nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(10,10,11,.88);
  backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--border);
}
.nav__inner {
  display: flex;
  align-items: center;
  gap: 0;
  height: 64px;
}
.nav__logo {
  font-size: 20px;
  font-weight: 800;
  letter-spacing: -.04em;
  color: var(--text-0);
  margin-right: 40px;
  flex-shrink: 0;
}
.nav__logo span { color: var(--accent); }
.nav__links {
  display: flex;
  gap: 28px;
  flex: 1;
}
.nav__links a {
  font-size: 14px;
  font-weight: 500;
  color: var(--text-1);
  transition: color var(--transition);
}
.nav__links a:hover,
.nav__links a.active { color: var(--text-0); }
.nav__actions {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-left: auto;
}
.nav__icon-btn {
  position: relative;
  width: 40px; height: 40px;
  border-radius: var(--radius-sm);
  display: flex; align-items: center; justify-content: center;
  color: var(--text-1);
  transition: background var(--transition), color var(--transition);
}
.nav__icon-btn:hover { background: var(--bg-2); color: var(--text-0); }
.nav__icon-btn svg { width: 20px; height: 20px; }
.nav__cart-count {
  position: absolute;
  top: 5px; right: 5px;
  width: 16px; height: 16px;
  border-radius: 50%;
  background: var(--accent);
  color: #111;
  font-size: 9px;
  font-weight: 700;
  display: flex; align-items: center; justify-content: center;
}
.nav__search {
  display: flex;
  align-items: center;
  gap: 8px;
  background: var(--bg-2);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 0 12px;
  height: 36px;
  width: 220px;
  transition: border-color var(--transition), width var(--transition);
}
.nav__search:focus-within { border-color: var(--accent); width: 260px; }
.nav__search svg { width: 15px; height: 15px; color: var(--text-2); flex-shrink: 0; }
.nav__search input {
  background: none;
  border: none;
  outline: none;
  color: var(--text-0);
  font-family: inherit;
  font-size: 13px;
  width: 100%;
}
.nav__search input::placeholder { color: var(--text-2); }

/* ── HERO ─────────────────────────────────────────────── */
.hero {
  position: relative;
  min-height: 560px;
  display: flex;
  align-items: center;
  overflow: hidden;
}
.hero__bg {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 80% 60% at 70% 50%, rgba(232,196,106,.07) 0%, transparent 70%),
    linear-gradient(135deg, #0d0d10 0%, #16161c 100%);
}
.hero__grid-overlay {
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(var(--border) 1px, transparent 1px),
    linear-gradient(90deg, var(--border) 1px, transparent 1px);
  background-size: 48px 48px;
  opacity: .25;
  mask-image: radial-gradient(ellipse 90% 90% at center, black, transparent);
}
.hero__content {
  position: relative;
  z-index: 1;
  max-width: 620px;
  padding: 80px 0;
}
.hero__eyebrow {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 20px;
}
.hero__eyebrow-line {
  width: 32px; height: 2px;
  background: var(--accent);
  border-radius: 2px;
}
.hero__eyebrow span {
  font-size: 12px;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--accent);
}
.hero h1 {
  font-size: clamp(36px, 5.5vw, 64px);
  font-weight: 800;
  letter-spacing: -.04em;
  line-height: 1.05;
  margin-bottom: 20px;
}
.hero h1 .highlight {
  background: linear-gradient(90deg, var(--accent), #f5d98a);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}
.hero__sub {
  font-size: 17px;
  color: var(--text-1);
  max-width: 480px;
  margin-bottom: 36px;
  line-height: 1.65;
}
.hero__ctas {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 12px 24px;
  border-radius: var(--radius-sm);
  font-size: 14px;
  font-weight: 600;
  transition: background var(--transition), transform var(--transition), box-shadow var(--transition);
}
.btn:active { transform: scale(.97); }
.btn--primary {
  background: var(--accent);
  color: #111;
  box-shadow: 0 0 0 0 var(--accent-glow);
}
.btn--primary:hover {
  background: var(--accent-dim);
  box-shadow: 0 4px 20px var(--accent-glow);
}
.btn--ghost {
  border: 1px solid var(--border);
  color: var(--text-0);
}
.btn--ghost:hover { background: var(--bg-2); }
.btn svg { width: 16px; height: 16px; }

.hero__stats {
  display: flex;
  gap: 36px;
  margin-top: 52px;
  padding-top: 32px;
  border-top: 1px solid var(--border);
}
.hero__stat-value {
  font-size: 24px;
  font-weight: 800;
  letter-spacing: -.03em;
  color: var(--text-0);
}
.hero__stat-label {
  font-size: 12px;
  color: var(--text-2);
  margin-top: 2px;
}

/* ── MARQUEE ──────────────────────────────────────────── */
.marquee-strip {
  background: var(--accent);
  overflow: hidden;
  padding: 10px 0;
}
.marquee-track {
  display: flex;
  gap: 0;
  white-space: nowrap;
  animation: marquee 30s linear infinite;
}
.marquee-track span {
  padding: 0 20px;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: #111;
}
.marquee-track span::after {
  content: '·';
  margin-left: 20px;
  opacity: .4;
}
@keyframes marquee {
  from { transform: translateX(0); }
  to   { transform: translateX(-50%); }
}

/* ── CATEGORIES ───────────────────────────────────────── */
.categories { padding: 72px 0; }
.categories__grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 12px;
}
.cat-card {
  background: var(--bg-2);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 20px 12px;
  text-align: center;
  cursor: pointer;
  transition: background var(--transition), border-color var(--transition), transform var(--transition);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
}
.cat-card:hover {
  background: var(--bg-3);
  border-color: var(--accent);
  transform: translateY(-3px);
}
.cat-card__icon {
  width: 44px; height: 44px;
  border-radius: 10px;
  background: var(--bg-3);
  display: flex; align-items: center; justify-content: center;
  font-size: 22px;
  transition: background var(--transition);
}
.cat-card:hover .cat-card__icon { background: var(--accent-glow); }
.cat-card__name {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-1);
}

/* ── FEATURED PRODUCTS ────────────────────────────────── */
.featured { padding: 0 0 72px; }
.products-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}
.product-card {
  background: var(--bg-1);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: border-color var(--transition), transform var(--transition), box-shadow var(--transition);
  cursor: pointer;
}
.product-card:hover {
  border-color: rgba(232,196,106,.35);
  transform: translateY(-4px);
  box-shadow: 0 12px 40px rgba(0,0,0,.45);
}
.product-card__img-wrap {
  position: relative;
  aspect-ratio: 1;
  background: var(--bg-2);
  overflow: hidden;
}
.product-card__img-wrap img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform .4s ease;
}
.product-card:hover .product-card__img-wrap img { transform: scale(1.06); }
.product-card__badges {
  position: absolute;
  top: 12px; left: 12px;
  display: flex; flex-direction: column; gap: 5px;
}
.product-card__wish {
  position: absolute;
  top: 10px; right: 10px;
  width: 32px; height: 32px;
  border-radius: 50%;
  background: rgba(10,10,11,.7);
  backdrop-filter: blur(6px);
  display: flex; align-items: center; justify-content: center;
  color: var(--text-2);
  transition: color var(--transition), background var(--transition);
}
.product-card__wish:hover { color: var(--red); background: rgba(232,93,93,.12); }
.product-card__wish.active { color: var(--red); }
.product-card__wish svg { width: 15px; height: 15px; }
.product-card__body { padding: 16px; flex: 1; display: flex; flex-direction: column; }
.product-card__brand {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--text-2);
  margin-bottom: 5px;
}
.product-card__name {
  font-size: 14px;
  font-weight: 600;
  line-height: 1.4;
  margin-bottom: 10px;
  flex: 1;
}
.product-card__rating {
  display: flex;
  align-items: center;
  gap: 5px;
  margin-bottom: 12px;
}
.stars { display: flex; gap: 2px; }
.stars svg { width: 11px; height: 11px; fill: var(--accent); color: var(--accent); }
.stars svg.empty { fill: var(--bg-3); color: var(--bg-3); }
.rating-count { font-size: 11px; color: var(--text-2); }
.product-card__footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}
.product-card__price { display: flex; align-items: baseline; gap: 7px; }
.price-current {
  font-size: 18px;
  font-weight: 800;
  letter-spacing: -.02em;
  color: var(--text-0);
}
.price-old {
  font-size: 12px;
  color: var(--text-2);
  text-decoration: line-through;
}
.btn--cart {
  width: 34px; height: 34px;
  border-radius: var(--radius-sm);
  background: var(--accent);
  color: #111;
  display: flex; align-items: center; justify-content: center;
  transition: background var(--transition), transform var(--transition);
  flex-shrink: 0;
}
.btn--cart:hover { background: var(--accent-dim); }
.btn--cart:active { transform: scale(.9); }
.btn--cart svg { width: 16px; height: 16px; }

/* ── DEALS BANNER ─────────────────────────────────────── */
.deals { padding: 0 0 72px; }
.deals__grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
}
.deal-hero {
  background: linear-gradient(135deg, #16161c, #1e1c14);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 44px 40px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  min-height: 320px;
  position: relative;
  overflow: hidden;
}
.deal-hero::before {
  content: '';
  position: absolute;
  right: -40px; top: -40px;
  width: 280px; height: 280px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(232,196,106,.12) 0%, transparent 70%);
  pointer-events: none;
}
.deal-hero__tag {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: 12px;
}
.deal-hero h3 {
  font-size: clamp(22px, 2.5vw, 30px);
  font-weight: 800;
  letter-spacing: -.03em;
  line-height: 1.15;
  margin-bottom: 14px;
}
.deal-hero p {
  font-size: 14px;
  color: var(--text-1);
  max-width: 340px;
  margin-bottom: 24px;
}
.countdown {
  display: flex;
  gap: 10px;
  margin-bottom: 28px;
}
.countdown__unit {
  background: var(--bg-3);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 8px 12px;
  text-align: center;
  min-width: 54px;
}
.countdown__num {
  font-size: 22px;
  font-weight: 800;
  letter-spacing: -.03em;
  font-variant-numeric: tabular-nums;
  display: block;
}
.countdown__label {
  font-size: 9px;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--text-2);
  margin-top: 2px;
  display: block;
}

.deals__stack {
  display: flex;
  flex-direction: column;
  gap: 16px;
}
.deal-card {
  background: var(--bg-1);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 18px;
  display: flex;
  gap: 16px;
  align-items: center;
  cursor: pointer;
  transition: border-color var(--transition), background var(--transition);
}
.deal-card:hover { border-color: rgba(232,196,106,.3); background: var(--bg-2); }
.deal-card__img {
  width: 80px; height: 80px;
  border-radius: var(--radius-sm);
  background: var(--bg-2);
  overflow: hidden;
  flex-shrink: 0;
}
.deal-card__img img { width: 100%; height: 100%; object-fit: cover; }
.deal-card__info { flex: 1; min-width: 0; }
.deal-card__name {
  font-size: 14px;
  font-weight: 600;
  margin-bottom: 4px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.deal-card__savings {
  font-size: 12px;
  color: var(--red);
  font-weight: 600;
  margin-bottom: 8px;
}
.deal-card__progress-label {
  display: flex;
  justify-content: space-between;
  font-size: 10px;
  color: var(--text-2);
  margin-bottom: 5px;
}
.deal-card__bar {
  height: 4px;
  background: var(--bg-3);
  border-radius: 2px;
  overflow: hidden;
}
.deal-card__bar-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--accent), var(--accent-dim));
  border-radius: 2px;
  transition: width .8s ease;
}

/* ── EDITORIAL ────────────────────────────────────────── */
.editorial { padding: 0 0 80px; }
.editorial__grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  gap: 20px;
}
.editorial-card {
  background: var(--bg-1);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  overflow: hidden;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  transition: border-color var(--transition), transform var(--transition), box-shadow var(--transition);
}
.editorial-card:hover {
  border-color: rgba(232,196,106,.3);
  transform: translateY(-3px);
  box-shadow: 0 10px 36px rgba(0,0,0,.4);
}
.editorial-card__img {
  aspect-ratio: 16/9;
  overflow: hidden;
  background: var(--bg-2);
}
.editorial-card--featured .editorial-card__img { aspect-ratio: 4/3; }
.editorial-card__img img {
  width: 100%; height: 100%;
  object-fit: cover;
  transition: transform .5s ease;
}
.editorial-card:hover .editorial-card__img img { transform: scale(1.06); }
.editorial-card__body { padding: 20px; flex: 1; display: flex; flex-direction: column; }
.editorial-card__meta {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 10px;
}
.editorial-card__cat {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--accent);
}
.editorial-card__date {
  font-size: 11px;
  color: var(--text-2);
}
.editorial-card h3 {
  font-size: 16px;
  font-weight: 700;
  line-height: 1.35;
  margin-bottom: 8px;
}
.editorial-card--featured h3 { font-size: 20px; }
.editorial-card p {
  font-size: 13px;
  color: var(--text-1);
  line-height: 1.6;
  flex: 1;
}
.editorial-card__read {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: 16px;
  font-size: 12px;
  font-weight: 600;
  color: var(--accent);
}
.editorial-card__read svg { width: 13px; height: 13px; }

/* ── NEWSLETTER ───────────────────────────────────────── */
.newsletter {
  background: var(--bg-1);
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
  padding: 64px 0;
}
.newsletter__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 40px;
}
.newsletter__copy h2 {
  font-size: clamp(18px, 2.5vw, 24px);
  font-weight: 800;
  letter-spacing: -.03em;
  margin-bottom: 6px;
}
.newsletter__copy p { font-size: 14px; color: var(--text-1); }
.newsletter__form {
  display: flex;
  gap: 10px;
  flex-shrink: 0;
}
.newsletter__input {
  background: var(--bg-2);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 0 16px;
  height: 44px;
  color: var(--text-0);
  font-family: inherit;
  font-size: 14px;
  width: 280px;
  outline: none;
  transition: border-color var(--transition);
}
.newsletter__input:focus { border-color: var(--accent); }
.newsletter__input::placeholder { color: var(--text-2); }

/* ── FOOTER ───────────────────────────────────────────── */
.footer {
  padding: 56px 0 32px;
  background: var(--bg-0);
}
.footer__top {
  display: grid;
  grid-template-columns: 1.8fr 1fr 1fr 1fr;
  gap: 40px;
  margin-bottom: 48px;
}
.footer__brand p {
  font-size: 13px;
  color: var(--text-2);
  line-height: 1.7;
  margin-top: 12px;
  max-width: 240px;
}
.footer__social {
  display: flex;
  gap: 8px;
  margin-top: 20px;
}
.footer__social a {
  width: 34px; height: 34px;
  border-radius: var(--radius-sm);
  background: var(--bg-2);
  border: 1px solid var(--border);
  display: flex; align-items: center; justify-content: center;
  color: var(--text-2);
  font-size: 14px;
  transition: border-color var(--transition), color var(--transition);
}
.footer__social a:hover { border-color: var(--accent); color: var(--accent); }
.footer__col h4 {
  font-size: 12px;
  font-weight: 700;
  letter-spacing: .06em;
  text-transform: uppercase;
  color: var(--text-2);
  margin-bottom: 16px;
}
.footer__col ul { display: flex; flex-direction: column; gap: 10px; }
.footer__col ul a {
  font-size: 13px;
  color: var(--text-1);
  transition: color var(--transition);
}
.footer__col ul a:hover { color: var(--text-0); }
.footer__bottom {
  border-top: 1px solid var(--border);
  padding-top: 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}
.footer__copy { font-size: 12px; color: var(--text-2); }
.footer__badges { display: flex; gap: 8px; }
.pay-badge {
  background: var(--bg-2);
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 4px 8px;
  font-size: 10px;
  font-weight: 700;
  color: var(--text-2);
  letter-spacing: .04em;
}

/* ── TOAST ────────────────────────────────────────────── */
.toast-container {
  position: fixed;
  bottom: 24px; right: 24px;
  z-index: 999;
  display: flex;
  flex-direction: column;
  gap: 10px;
  pointer-events: none;
}
.toast {
  background: var(--bg-2);
  border: 1px solid var(--border);
  border-left: 3px solid var(--accent);
  border-radius: var(--radius-sm);
  padding: 12px 16px;
  font-size: 13px;
  color: var(--text-0);
  box-shadow: var(--shadow);
  display: flex;
  align-items: center;
  gap: 10px;
  animation: toast-in .25s ease, toast-out .25s ease forwards;
  animation-delay: 0s, 2.75s;
  pointer-events: auto;
}
.toast svg { width: 15px; height: 15px; color: var(--accent); flex-shrink: 0; }
@keyframes toast-in  { from { opacity:0; transform: translateY(12px); } to { opacity:1; transform: none; } }
@keyframes toast-out { from { opacity:1; } to { opacity:0; transform: translateY(-6px); } }

/* ── RESPONSIVE ───────────────────────────────────────── */
@media (max-width: 1024px) {
  .products-grid { grid-template-columns: repeat(2, 1fr); }
  .categories__grid { grid-template-columns: repeat(3, 1fr); }
  .editorial__grid { grid-template-columns: 1fr 1fr; }
  .editorial-card--featured { grid-column: span 2; }
  .footer__top { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 768px) {
  .nav__links { display: none; }
  .nav__search { width: 180px; }
  .hero__stats { gap: 20px; }
  .deals__grid { grid-template-columns: 1fr; }
  .newsletter__inner { flex-direction: column; text-align: center; }
  .newsletter__form { flex-direction: column; width: 100%; max-width: 360px; }
  .newsletter__input { width: 100%; }
  .editorial__grid { grid-template-columns: 1fr; }
  .editorial-card--featured { grid-column: span 1; }
  .footer__top { grid-template-columns: 1fr; }
}
@media (max-width: 480px) {
  .categories__grid { grid-template-columns: repeat(3, 1fr); }
  .products-grid { grid-template-columns: 1fr 1fr; gap: 12px; }
}
