", direction=None, fact=None, file_name='/workspace/sandbox/control/shopping-home-page--framework-vanilla-js--style-dark/claude-sonnet-4.6__s1/styles.css', full_command_text=None, has_write_file_redirection=None, hook_message=None, intention='Create file', new_file_contents="/* ── Reset & Base ─────────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg-0:       #0a0a0b;
  --bg-1:       #111113;
  --bg-2:       #1a1a1e;
  --bg-3:       #222228;
  --border:     #2a2a32;
  --accent:     #e8c46a;
  --accent-dim: #c9a84c;
  --accent-glow:rgba(232,196,106,.18);
  --red:        #e85d5d;
  --text-0:     #f0f0f2;
  --text-1:     #b0b0b8;
  --text-2:     #6a6a78;
  --radius-sm:  6px;
  --radius-md:  12px;
  --radius-lg:  20px;
  --shadow:     0 4px 24px rgba(0,0,0,.55);
  --transition: .22s cubic-bezier(.4,0,.2,1);
  --font:       'Inter', system-ui, -apple-system, sans-serif;
}

html { scroll-behavior: smooth; }

body {
  background: var(--bg-0);
  color: var(--text-0);
  font-family: var(--font);
  font-size: 15px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; text-decoration: none; }
img { display: block; max-width: 100%; }
button { cursor: pointer; border: none; background: none; font-family: inherit; }
ul { list-style: none; }

/* ── Utilities ────────────────────────────────────────── */
.container {
  max-width: 1240px;
  margin: 0 auto;
  padding: 0 24px;
}

.badge {
  display: inline-block;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .06em;
  text-transform: uppercase;
  padding: 3px 9px;
  border-radius: 4px;
}
.badge--accent { background: var(--accent); color: #111; }
.badge--red    { background: var(--red);    color: #fff; }
.badge--ghost  { border: 1px solid var(--border); color: var(--text-1); }

.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: 32px;
  gap: 16px;
}
.section-header h2 {
  font-size: clamp(20px, 2.5vw, 26px);
  font-weight: 700;
  letter-spacing: -.02em;
}
.section-header h2 span { color: var(--accent); }
.view-all {
  font-size: 13px;
  font-weight: 600;
  color: var(--accent);
  white-space: nowrap;
  display: flex;
  align-items: center;
  gap: 4px;
  transition: gap var(--transition);
}
.view-all:hover { gap: 8px; }
.view-all svg { width: 14px; height: 14px; }

/* ── NAV ──────────────────────────────────────────────── */
.nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(10,10,11,.88);
  backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--border);
}
.nav__inner {
  display: flex;
  align-items: center;
  gap: 0;
  height: 64px;
}
.nav__logo {
  font-size: 20px;
  font-weight: 800;
  letter-spacing: -.04em;
  color: var(--text-0);
  margin-right: 40px;
  flex-shrink: 0;
}
.nav__logo span { color: var(--accent); }
.nav__links {
  display: flex;
  gap: 28px;
  flex: 1;
}
.nav__links a {
  font-size: 14px;
  font-weight: 500;
  color: var(--text-1);
  transition: color var(--transition);
}
.nav__links a:hover,
.nav__links a.active { color: var(--text-0); }
.nav__actions {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-left: auto;
}
.nav__icon-btn {
  position: relative;
  width: 40px; height: 40px;
  border-radius: var(--radius-sm);
  display: flex; align-items: center; justify-content: center;
  color: var(--text-1);
  transition: background var(--transition), color var(--transition);
}
.nav__icon-btn:hover { background: var(--bg-2); color: var(--text-0); }
.nav__icon-btn svg { width: 20px; height: 20px; }
.nav__cart-count {
  position: absolute;
  top: 5px; right: 5px;
  width: 16px; height: 16px;
  border-radius: 50%;
  background: var(--accent);
  color: #111;
  font-size: 9px;
  font-weight: 700;
  display: flex; align-items: center; justify-content: center;
}
.nav__search {
  display: flex;
  align-items: center;
  gap: 8px;
  background: var(--bg-2);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 0 12px;
  height: 36px;
  width: 220px;
  transition: border-color var(--transition), width var(--transition);
}
.nav__search:focus-within { border-color: var(--accent); width: 260px; }
.nav__search svg { width: 15px; height: 15px; color: var(--text-2); flex-shrink: 0; }
.nav__search input {
  background: none;
  border: none;
  outline: none;
  color: var(--text-0);
  font-family: inherit;
  font-size: 13px;
  width: 100%;
}
.nav__search input::placeholder { color: var(--text-2); }

/* ── HERO ─────────────────────────────────────────────── */
.hero {
  position: relative;
  min-height: 560px;
  display: flex;
  align-items: center;
  overflow: hidden;
}
.hero__bg {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 80% 60% at 70% 50%, rgba(232,196,106,.07) 0%, transparent 70%),
    linear-gradient(135deg, #0d0d10 0%, #16161c 100%);
}
.hero__grid-overlay {
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(var(--border) 1px, transparent 1px),
    linear-gradient(90deg, var(--border) 1px, transparent 1px);
  background-size: 48px 48px;
  opacity: .25;
  mask-image: radial-gradient(ellipse 90% 90% at center, black, transparent);
}
.hero__content {
  position: relative;
  z-index: 1;
  max-width: 620px;
  padding: 80px 0;
}
.hero__eyebrow {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 20px;
}
.hero__eyebrow-line {
  width: 32px; height: 2px;
  background: var(--accent);
  border-radius: 2px;
}
.hero__eyebrow span {
  font-size: 12px;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--accent);
}
.hero h1 {
  font-size: clamp(36px, 5.5vw, 64px);
  font-weight: 800;
  letter-spacing: -.04em;
  line-height: 1.05;
  margin-bottom: 20px;
}
.hero h1 .highlight {
  background: linear-gradient(90deg, var(--accent), #f5d98a);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}
.hero__sub {
  font-size: 17px;
  color: var(--text-1);
  max-width: 480px;
  margin-bottom: 36px;
  line-height: 1.65;
}
.hero__ctas {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 12px 24px;
  border-radius: var(--radius-sm);
  font-size: 14px;
  font-weight: 600;
  transition: background var(--transition), transform var(--transition), box-shadow var(--transition);
}
.btn:active { transform: scale(.97); }
.btn--primary {
  background: var(--accent);
  color: #111;
  box-shadow: 0 0 0 0 var(--accent-glow);
}
.btn--primary:hover {
  background: var(--accent-dim);
  box-shadow: 0 4px 20px var(--accent-glow);
}
.btn--ghost {
  border: 1px solid var(--border);
  color: var(--text-0);
}
.btn--ghost:hover { background: var(--bg-2); }
.btn svg { width: 16px; height: 16px; }

.hero__stats {
  display: flex;
  gap: 36px;
  margin-top: 52px;
  padding-top: 32px;
  border-top: 1px solid var(--border);
}
.hero__stat-value {
  font-size: 24px;
  font-weight: 800;
  letter-spacing: -.03em;
  color: var(--text-0);
}
.hero__stat-label {
  font-size: 12px;
  color: var(--text-2);
  margin-top: 2px;
}

/* ── MARQUEE ──────────────────────────────────────────── */
.marquee-strip {
  background: var(--accent);
  overflow: hidden;
  padding: 10px 0;
}
.marquee-track {
  display: flex;
  gap: 0;
  white-space: nowrap;
  animation: marquee 30s linear infinite;
}
.marquee-track span {
  padding: 0 20px;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: #111;
}
.marquee-track span::after {
  content: '·';
  margin-left: 20px;
  opacity: .4;
}
@keyframes marquee {
  from { transform: translateX(0); }
  to   { transform: translateX(-50%); }
}

/* ── CATEGORIES ───────────────────────────────────────── */
.categories { padding: 72px 0; }
.categories__grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 12px;
}
.cat-card {
  background: var(--bg-2);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 20px 12px;
  text-align: center;
  cursor: pointer;
  transition: background var(--transition), border-color var(--transition), transform var(--transition);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
}
.cat-card:hover {
  background: var(--bg-3);
  border-color: var(--accent);
  transform: translateY(-3px);
}
.cat-card__icon {
  width: 44px; height: 44px;
  border-radius: 10px;
  background: var(--bg-3);
  display: flex; align-items: center; justify-content: center;
  font-size: 22px;
  transition: background var(--transition);
}
.cat-card:hover .cat-card__icon { background: var(--accent-glow); }
.cat-card__name {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-1);
}

/* ── FEATURED PRODUCTS ────────────────────────────────── */
.featured { padding: 0 0 72px; }
.products-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}
.product-card {
  background: var(--bg-1);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: border-color var(--transition), transform var(--transition), box-shadow var(--transition);
  cursor: pointer;
}
.product-card:hover {
  border-color: rgba(232,196,106,.35);
  transform: translateY(-4px);
  box-shadow: 0 12px 40px rgba(0,0,0,.45);
}
.product-card__img-wrap {
  position: relative;
  aspect-ratio: 1;
  background: var(--bg-2);
  overflow: hidden;
}
.product-card__img-wrap img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform .4s ease;
}
.product-card:hover .product-card__img-wrap img { transform: scale(1.06); }
.product-card__badges {
  position: absolute;
  top: 12px; left: 12px;
  display: flex; flex-direction: column; gap: 5px;
}
.product-card__wish {
  position: absolute;
  top: 10px; right: 10px;
  width: 32px; height: 32px;
  border-radius: 50%;
  background: rgba(10,10,11,.7);
  backdrop-filter: blur(6px);
  display: flex; align-items: center; justify-content: center;
  color: var(--text-2);
  transition: color var(--transition), background var(--transition);
}
.product-card__wish:hover { color: var(--red); background: rgba(232,93,93,.12); }
.product-card__wish.active { color: var(--red); }
.product-card__wish svg { width: 15px; height: 15px; }
.product-card__body { padding: 16px; flex: 1; display: flex; flex-direction: column; }
.product-card__brand {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--text-2);
  margin-bottom: 5px;
}
.product-card__name {
  font-size: 14px;
  font-weight: 600;
  line-height: 1.4;
  margin-bottom: 10px;
  flex: 1;
}
.product-card__rating {
  display: flex;
  align-items: center;
  gap: 5px;
  margin-bottom: 12px;
