*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg-0:       #0a0a0b;
  --bg-1:       #111113;
  --bg-2:       #1a1a1e;
  --bg-3:       #222228;
  --border:     #2a2a32;
  --accent:     #e8c46a;
  --accent-dim: #c9a84c;
  --accent-glow:rgba(232,196,106,.18);
  --red:        #e85d5d;
  --text-0:     #f0f0f2;
  --text-1:     #b0b0b8;
  --text-2:     #6a6a78;
  --radius-sm:  6px;
  --radius-md:  12px;
  --radius-lg:  20px;
  --shadow:     0 4px 24px rgba(0,0,0,.55);
  --transition: .22s cubic-bezier(.4,0,.2,1);
  --font:       'Inter', system-ui, -apple-system, sans-serif;
}

html { scroll-behavior: smooth; }

body {
  background: var(--bg-0);
  color: var(--text-0);
  font-family: var(--font);
  font-size: 15px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; text-decoration: none; }
img { display: block; max-width: 100%; }
button { cursor: pointer; border: none; background: none; font-family: inherit; }
ul { list-style: none; }

/* ── Utilities ────────────────────────────────────────── */
.container {
  max-width: 1240px;
  margin: 0 auto;
  padding: 0 24px;
}

.badge {
  display: inline-block;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .06em;
  text-transform: uppercase;
  padding: 3px 9px;
  border-radius: 4px;
}
.badge--accent { background: var(--accent); color: #111; }
.badge--red    { background: var(--red);    color: #fff; }
.badge--ghost  { border: 1px solid var(--border); color: var(--text-1); }

.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: 32px;
  gap: 16px;
}
.section-header h2 {
  font-size: clamp(20px, 2.5vw, 26px);
  font-weight: 700;
  letter-spacing: -.02em;
}
