.view-all {
  font-size: 13px;
  font-weight: 600;
  color: var(--accent);
  white-space: nowrap;
  display: flex;
  align-items: center;
  gap: 4px;
  transition: gap var(--transition);
}
.view-all:hover { gap: 8px; }
.view-all svg { width: 14px; height: 14px; }

