+/* ── Cart State ───────────────────────────────────────── */
+let cartCount = 0;
+const cartCountEl = document.getElementById('cart-count');
+
+function updateCartCount() {
+  cartCountEl.textContent = cartCount;
+  cartCountEl.style.transform = 'scale(1.4)';
+  setTimeout(() => cartCountEl.style.transform = '', 200);
+}
+
+/* ── Toast ────────────────────────────────────────────── */
+function showToast(msg) {
+  const container = document.getElementById('toast-container');
+  const toast = document.createElement('div');
+  toast.className = 'toast';
+  toast.innerHTML = `
+    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5">
+      <polyline points="20 6 9 17 4 12"/>
+    </svg>
+    <span>${msg}</span>`;
+  container.appendChild(toast);
+  setTimeout(() => toast.remove(), 3200);
+}
+
+/* ── Add to Cart ──────────────────────────────────────── */
+document.querySelectorAll('.btn--cart').forEach(btn => {
+  btn.addEventListener('click', (e) => {
+    e.stopPropagation();
+    const card = btn.closest('.product-card');
+    const name = card.querySelector('.product-card__name').textContent.trim();
+    cartCount++;
+    updateCartCount();
+    showToast(`"${name}" added to cart`);
+  });
+});
+
+/* ── Wishlist Toggle ──────────────────────────────────── */
+document.querySelectorAll('.product-card__wish').forEach(btn => {
+  btn.addEventListener('click', (e) => {
+    e.stopPropagation();
+    btn.classList.toggle('active');
+    const name = btn.closest('.product-card').querySelector('.product-card__name').textContent.trim();
+    const action = btn.classList.contains('active') ? 'saved to' : 'removed from';
+    showToast(`"${name}" ${action} wishlist`);
+  });
+});
+
+/* ── Countdown Timer ──────────────────────────────────── */
+function startCountdown(endTimestamp) {
+  const els = {
+    h: document.getElementById('cd-hours'),
+    m: document.getElementById('cd-mins'),
+    s: document.getElementById('cd-secs'),
+  };
+
+  function tick() {
+    const diff = Math.max(0, endTimestamp - Date.now());
+    const h = Math.floor(diff / 3600000);
+    const m = Math.floor((diff % 3600000) / 60000);
+    const s = Math.floor((diff % 60000) / 1000);
+    els.h.textContent = String(h).padStart(2, '0');
+    els.m.textContent = String(m).padStart(2, '0');
+    els.s.textContent = String(s).padStart(2, '0');
+    if (diff > 0) requestAnimationFrame(() => setTimeout(tick, 1000));
+  }
+  tick();
+}
+startCountdown(Date.now() + 6 * 3600000 + 43 * 60000 + 17000);
+
+/* ── Animate deal bars on scroll ─────────────────────── */
+const barObserver = new IntersectionObserver((entries) => {
+  entries.forEach(entry => {
+    if (entry.isIntersecting) {
+      const fill = entry.target;
+      const pct = fill.dataset.pct;
+      fill.style.width = pct + '%';
+      barObserver.unobserve(fill);
+    }
+  });
+}, { threshold: 0.3 });
+
+document.querySelectorAll('.deal-card__bar-fill').forEach(el => {
+  el.style.width = '0%';
+  barObserver.observe(el);
+});
+
+/* ── Newsletter submit ────────────────────────────────── */
+document.getElementById('newsletter-form').addEventListener('submit', (e) => {
+  e.preventDefault();
+  const input = e.target.querySelector('input');
+  if (input.value.trim()) {
+    showToast('You\'re subscribed! Welcome aboard 🎉');
+    input.value = '';
+  }
+});
+
+/* ── Hero entrance animation ─────────────────────────── */
+(function () {
+  const hero = document.querySelector('.hero__content');
+  if (!hero) return;
+  hero.style.opacity = '0';
+  hero.style.transform = 'translateY(24px)';
+  hero.style.transition = 'opacity .6s ease, transform .6s ease';
+  requestAnimationFrame(() => {
+    hero.style.opacity = '1';
+    hero.style.transform = 'translateY(0)';
+  });
+})();
+
+/* ── Fade-in sections on scroll ──────────────────────── */
+const fadeObserver = new IntersectionObserver((entries) => {
+  entries.forEach(entry => {
+    if (entry.isIntersecting) {
+      entry.target.style.opacity = '1';
+      entry.target.style.transform = 'translateY(0)';
+      fadeObserver.unobserve(entry.target);
+    }
+  });
+}, { threshold: 0.08 });
+
+document.querySelectorAll('.product-card, .deal-card, .editorial-card, .cat-card, .deal-hero').forEach(el => {
+  el.style.opacity = '0';
+  el.style.transform = 'translateY(20px)';
+  el.style.transition = 'opacity .45s ease, transform .45s ease, border-color .22s cubic-bezier(.4,0,.2,1), box-shadow .22s cubic-bezier(.4,0,.2,1)';
+  fadeObserver.observe(el);
+});
+
+/* ── Category click ───────────────────────────────────── */
